);

CREATE TABLE authors (
    id INTEGER PRIMARY KEY,
    first_name TEXT,
    last_name TEXT,
    email TEXT,
    nationality TEXT,
    birth_date DATE,
    biography TEXT,
    website TEXT,
    created_at TIMESTAMP
);

CREATE TABLE categories (
    id INTEGER PRIMARY KEY,
    name TEXT,
    description TEXT,
    parent_category_id INTEGER,
    created_at TIMESTAMP
);

CREATE TABLE books (
    id INTEGER PRIMARY KEY,
    isbn13 TEXT,
    isbn10 TEXT,
    title TEXT,
    subtitle TEXT,
    publication_date DATE,
    pages INTEGER,
    language TEXT,
