    list_price NUMERIC(10,2),
    edition TEXT,
    description TEXT,
    publisher_id INTEGER,
    category_id INTEGER,
    created_at TIMESTAMP
);

CREATE TABLE book_authors (
    book_id INTEGER,
    author_id INTEGER,
    author_order INTEGER
);

CREATE TABLE customers (
    id INTEGER PRIMARY KEY,
    first_name TEXT,
    last_name TEXT,
    email TEXT,
    phone TEXT,
    address_line1 TEXT,
    address_line2 TEXT,
    city TEXT,
    state TEXT,
    postal_code TEXT,
    country TEXT,
    date_of_birth DATE,
    registration_date DATE,
