);

CREATE TABLE stores (
    id INTEGER PRIMARY KEY,
    name TEXT,
    address_line1 TEXT,
    address_line2 TEXT,
    city TEXT,
    state TEXT,
    postal_code TEXT,
    country TEXT,
    phone TEXT,
    manager_id INTEGER,
    opening_date DATE,
    store_type TEXT,
    square_footage INTEGER,
    created_at TIMESTAMP
);

CREATE TABLE inventory (
    id INTEGER PRIMARY KEY,
    book_id INTEGER,
    store_id INTEGER,
    quantity INTEGER,
    reorder_point INTEGER,
    reorder_quantity INTEGER,
    last_restocked_at TIMESTAMP,
    created_at TIMESTAMP
);

CREATE TABLE orders (
    id INTEGER PRIMARY KEY,
    order_number TEXT,
    customer_id INTEGER,
    store_id INTEGER,
    order_date TIMESTAMP,
    order_status TEXT,
    subtotal NUMERIC(10,2),
    tax_amount NUMERIC(10,2),
    total_amount NUMERIC(10,2),
    shipping_address TEXT,
    notes TEXT,
    created_at TIMESTAMP
);

CREATE TABLE order_items (
    id INTEGER PRIMARY KEY,
    order_id INTEGER,
    book_id INTEGER,
    quantity INTEGER,
    unit_price NUMERIC(10,2),
    discount NUMERIC(5,2),
    line_total NUMERIC(10,2)
);

CREATE TABLE payments (
    id INTEGER PRIMARY KEY,
    order_id INTEGER,
    payment_method TEXT,
    amount NUMERIC(10,2),
    currency TEXT,
    status TEXT,
    transaction_id TEXT,
